INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 1, 1, 'Что такое Vibe Coding?', '["Методология быстрой разработки с использованием ИИ-ассистентов", "Название конкретной нейросети для программирования", "Стиль написания кода с особым форматированием", "Библиотека Python для создания ботов"]', '[1]', '{"1": "✅ Правильно! Vibe Coding — это методология работы, где вы выступаете архитектором, а ИИ — исполнителем кода.", "2": "Неверно. Vibe Coding — это не конкретный инструмент, а методология работы с ИИ.", "3": "Неверно. Это не про стиль кода, а про способ разработки с помощью ИИ.", "4": "Неверно. Vibe Coding — методология, а не библиотека."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 1, 2, 'Какая ваша роль при использовании Vibe Coding?', '["Программист, который пишет весь код самостоятельно", "Архитектор решения, который ставит задачи ИИ", "Тестировщик готовых решений от ИИ", "Наблюдатель за работой нейросети"]', '[2]', '{"1": "Неверно. Vibe Coding предполагает делегирование написания кода ИИ, а не самостоятельное программирование.", "2": "✅ Правильно! Вы проектируете архитектуру и ставите задачи, а ИИ выполняет техническую реализацию.", "3": "Неверно. Роль шире — вы проектируете решение и управляете процессом, а не только тестируете.", "4": "Неверно. Вы активно участвуете в процессе, управляя ИИ, а не просто наблюдаете."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 1, 3, 'Для кого подходит курс Vibe Coding?', '["Только для профессиональных программистов", "Только для людей с техническим образованием", "Для всех, кто хочет создавать ботов без глубоких знаний программирования", "Только для специалистов по Data Science"]', '[3]', '{"1": "Неверно. Курс специально создан для людей БЕЗ глубоких знаний программирования.", "2": "Неверно. Техническое образование не требуется — курс объясняет все простым языком.", "3": "✅ Правильно! Курс подходит для любых специалистов, желающих автоматизировать задачи с помощью ботов.", "4": "Неверно. Курс универсален и не требует специализации в Data Science."}', 0);

-- Урок 2
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 2, 1, 'Что можно создать с помощью Vibe Coding?', '["Только простые чат-боты для Telegram", "Чат-боты, дашборды, автоматизацию документов и прототипы сервисов", "Только аналитические дашборды", "Исключительно системы обработки документов"]', '[2]', '{"1": "Неверно. Возможности Vibe Coding гораздо шире — это полный спектр решений для автоматизации.", "2": "✅ Правильно! Vibe Coding позволяет создавать разнообразные решения: от ботов до сложных систем обработки данных.", "3": "Неверно. Дашборды — это только одно из направлений применения методологии.", "4": "Неверно. Обработка документов — лишь часть возможностей Vibe Coding."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 2, 2, 'За какое время можно создать рабочий прототип чат-бота?', '["За 1-2 недели без знания программирования", "За 6 месяцев обучения программированию", "Только за 1-2 года опыта разработки", "Минимум год при наличии команды"]', '[1]', '{"1": "✅ Правильно! С помощью Vibe Coding простой бот создается за 1-2 недели даже без знания программирования.", "2": "Неверно. Vibe Coding ускоряет процесс — не нужно полгода учить программирование.", "3": "Неверно. Методология позволяет создавать решения быстро, без многолетнего опыта.", "4": "Неверно. Один человек с ИИ может создать бота за несколько недель."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 2, 3, 'Какое направление применения Vibe Coding включает работу с PDF и DOCX?', '["Создание чат-ботов", "Автоматизация обработки документов", "Разработка дашбордов", "Создание прототипов сервисов"]', '[2]', '{"1": "Неверно. Чат-боты могут работать с документами, но это специфическое направление — обработка документов.", "2": "✅ Правильно! Автоматизация обработки документов включает извлечение данных из PDF, DOCX и других форматов.", "3": "Неверно. Дашборды визуализируют данные, но не занимаются обработкой документов.", "4": "Неверно. Прототипы — это про тестирование идей, а обработка документов — отдельное направление."}', 0);

-- Урок 3
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 3, 1, 'Что такое API?', '["Специальная программа для создания ботов", "Интерфейс для взаимодействия между программами", "База данных для хранения сообщений", "Язык программирования для разработки"]', '[2]', '{"1": "Неверно. API — не программа, а способ обмена данными между приложениями.", "2": "✅ Правильно! API (Application Programming Interface) — это интерфейс, позволяющий программам общаться друг с другом.", "3": "Неверно. База данных хранит информацию, а API обеспечивает обмен данными.", "4": "Неверно. API — не язык программирования, а способ взаимодействия приложений."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 3, 2, 'Какая российская нейросеть используется в курсе?', '["ChatGPT", "GigaChat", "Claude", "YandexGPT"]', '[2]', '{"1": "Неверно. ChatGPT — зарубежная нейросеть от OpenAI.", "2": "✅ Правильно! GigaChat — российская нейросеть от Сбера, используемая для соблюдения требований по локализации данных.", "3": "Неверно. Claude — зарубежная нейросеть от Anthropic.", "4": "Неверно. YandexGPT — тоже российская, но в курсе используется GigaChat."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 3, 3, 'Что такое гибридный поиск в базе знаний?', '["Поиск только по ключевым словам", "Поиск только по векторным представлениям", "Комбинация векторного поиска и поиска по ключевым словам (BM25)", "Поиск в интернете через Google"]', '[3]', '{"1": "Неверно. Поиск только по ключевым словам (BM25) — это лишь часть гибридного подхода.", "2": "Неверно. Векторный поиск (FAISS) — также часть гибридного подхода, но не полная система.", "3": "✅ Правильно! Гибридный поиск объединяет FAISS (векторный поиск) и BM25 (ключевые слова) для максимальной точности.", "4": "Неверно. Гибридный поиск работает с локальной базой знаний, а не с интернетом."}', 0);

-- Урок 4
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 4, 1, 'Что важно при постановке задачи ИИ в Vibe Coding?', '["Писать максимально короткие запросы", "Четко описывать цель, контекст и желаемый результат", "Использовать только технические термины", "Просить ИИ самостоятельно догадаться о требованиях"]', '[2]', '{"1": "Неверно. Короткие запросы часто не содержат достаточно информации для качественного результата.", "2": "✅ Правильно! Чем точнее вы опишете задачу, контекст и ожидаемый результат, тем лучше будет код от ИИ.", "3": "Неверно. Важно использовать понятный язык, объясняя задачу простыми словами с контекстом.", "4": "Неверно. ИИ нужны четкие инструкции, а не догадки — это основа эффективной работы."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 4, 2, 'Как правильно работать с кодом, полученным от ИИ?', '["Сразу запускать без проверки", "Проверять, тестировать и постепенно улучшать", "Полностью переписывать самостоятельно", "Игнорировать ошибки и продолжать работу"]', '[2]', '{"1": "Неверно. Код нужно проверять и тестировать, даже если он от ИИ — это основа безопасности.", "2": "✅ Правильно! Итеративный подход: получили код → проверили → протестировали → уточнили → улучшили.", "3": "Неверно. Переписывание вручную теряет преимущества Vibe Coding — ИИ ускоряет процесс.", "4": "Неверно. Ошибки нужно исправлять сразу, запрашивая у ИИ доработку или объяснение."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (6, 4, 3, 'Что делать, если ИИ не понял вашу задачу с первого раза?', '["Отказаться от использования ИИ", "Уточнить запрос, добавить примеры и контекст", "Попробовать другую нейросеть", "Ждать, пока ИИ сам догадается"]', '[2]', '{"1": "Неверно. Если ИИ не понял, нужно уточнить запрос, а не отказываться от инструмента.", "2": "✅ Правильно! Уточнение задачи, добавление примеров и контекста помогает ИИ лучше понять требования.", "3": "Неверно. Сначала стоит улучшить промпт для текущей нейросети, а не сразу менять инструмент.", "4": "Неверно. ИИ работает на основе ваших инструкций — без уточнений он не улучшит результат."}', 0);

