INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 5, 1, 'Что такое виртуальное окружение в Python?', '["Отдельная версия операционной системы", "Изолированная среда для установки библиотек проекта", "Облачный сервер для запуска кода", "Графический интерфейс для разработки"]', '[2]', '{"1": "Неверно. Виртуальное окружение работает в текущей ОС, не создавая новую систему.", "2": "✅ Правильно! Виртуальное окружение изолирует зависимости проекта, предотвращая конфликты библиотек.", "3": "Неверно. Виртуальное окружение создается локально на вашем компьютере, а не в облаке.", "4": "Неверно. Это не интерфейс, а способ изоляции Python-библиотек для проекта."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 5, 2, 'Какая библиотека используется для создания Telegram-ботов в курсе?', '["telebot", "python-telegram-bot", "aiogram", "pyrogram"]', '[3]', '{"1": "Неверно. telebot — популярная библиотека, но в курсе используется aiogram для асинхронной работы.", "2": "Неверно. python-telegram-bot тоже хороша, но курс построен на aiogram.", "3": "✅ Правильно! aiogram — современная асинхронная библиотека для создания Telegram-ботов на Python.", "4": "Неверно. pyrogram больше для работы с Telegram API напрямую, а не для ботов."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 5, 3, 'Зачем нужна структура папок проекта?', '["Только для красоты кода", "Для организации файлов и масштабируемости проекта", "Это обязательное требование Python", "Чтобы код работал быстрее"]', '[2]', '{"1": "Неверно. Структура папок критически важна для поддержки и развития проекта, а не только для эстетики.", "2": "✅ Правильно! Четкая структура помогает ориентироваться в коде, добавлять функции и работать в команде.", "3": "Неверно. Python не требует конкретной структуры, но хорошая организация — признак профессионального подхода.", "4": "Неверно. Структура папок влияет на читаемость, а не на скорость выполнения кода."}', 0);

