INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 6, 1, 'Кто или что такое @BotFather?', '["Официальный бот Telegram для создания и управления ботами", "Веб-сайт для регистрации ботов", "Программа для разработки ботов", "Российский сервис для ботов"]', '[1]', '{"1": "✅ Правильно! @BotFather — официальный бот Telegram, через который создаются и настраиваются все боты.", "2": "Неверно. @BotFather — это бот внутри Telegram, а не внешний сайт.", "3": "Неверно. @BotFather — бот для управления, а не программа для разработки.", "4": "Неверно. @BotFather — официальный инструмент Telegram, доступный всем пользователям мессенджера."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 6, 2, 'Что такое токен бота?', '["Имя пользователя бота", "Уникальный ключ для доступа к боту через API", "Пароль от аккаунта Telegram", "Ссылка на бота"]', '[2]', '{"1": "Неверно. Имя пользователя (username) — это публичное имя бота, а токен — секретный ключ доступа.", "2": "✅ Правильно! Токен — это уникальный секретный ключ, который позволяет вашему коду управлять ботом через API.", "3": "Неверно. Токен не связан с паролем Telegram-аккаунта — это отдельный ключ для бота.", "4": "Неверно. Ссылка на бота (t.me/botname) публична, а токен — секретный ключ доступа."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 6, 3, 'Где нужно хранить токен бота?', '["В открытом виде в коде", "В файле .env или config.py, который не попадает в Git", "В названии бота", "В описании бота"]', '[2]', '{"1": "Неверно. Токен в открытом коде — серьезная уязвимость, любой получит доступ к вашему боту.", "2": "✅ Правильно! Токен должен храниться в .env файле и добавлен в .gitignore для безопасности.", "3": "Неверно. Название бота публично, а токен должен быть секретным.", "4": "Неверно. Описание бота видно всем, токен нельзя там хранить."}', 0);

