INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 7, 1, 'Какую команду обычно обрабатывает бот первой?', '["/help", "/start", "/menu", "/info"]', '[2]', '{"1": "Неверно. /help важна, но первая команда при запуске бота — это /start.", "2": "✅ Правильно! Команда /start — стандартная точка входа, с которой начинается взаимодействие с ботом.", "3": "Неверно. /menu может быть позже, но первая команда — /start.", "4": "Неверно. /info — дополнительная команда, базовая — это /start."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 7, 2, 'Что делает метод start_polling()?', '["Создает бота в Telegram", "Запускает бота и начинает обрабатывать сообщения", "Отправляет сообщения пользователям", "Сохраняет данные в базу"]', '[2]', '{"1": "Неверно. Бот создается через @BotFather, а start_polling() запускает обработку сообщений.", "2": "✅ Правильно! start_polling() запускает бота в режиме polling — постоянной проверки новых сообщений.", "3": "Неверно. Отправка сообщений — отдельная функция, start_polling() запускает слушатель.", "4": "Неверно. Сохранение данных — это другая задача, start_polling() запускает прослушивание обновлений."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 7, 3, 'Как бот обрабатывает текстовые сообщения от пользователей?', '["Автоматически отвечает на все сообщения одинаково", "Через обработчики (handlers), которые реагируют на определенные события", "Сохраняет их в файл без обработки", "Пересылает сообщения администратору"]', '[2]', '{"1": "Неверно. Бот может отвечать по-разному в зависимости от настроенных обработчиков.", "2": "✅ Правильно! Handlers (обработчики) ловят события (команды, текст, кнопки) и выполняют нужные действия.", "3": "Неверно. Сохранение возможно, но сначала нужны обработчики для реакции на сообщения.", "4": "Неверно. Пересылка — одна из возможностей, но основа работы — это handlers."}', 0);

-- Урок 8
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 8, 1, 'Чем InlineKeyboard отличается от ReplyKeyboard?', '["InlineKeyboard появляется под сообщением, ReplyKeyboard заменяет клавиатуру", "InlineKeyboard — только для админов", "ReplyKeyboard работает быстрее", "Никакой разницы нет"]', '[1]', '{"1": "✅ Правильно! InlineKeyboard — кнопки под сообщением, ReplyKeyboard — кнопки вместо обычной клавиатуры телефона.", "2": "Неверно. Оба типа кнопок доступны всем пользователям, разница в расположении.", "3": "Неверно. Скорость одинакова, разница в пользовательском интерфейсе.", "4": "Неверно. Это два разных типа клавиатур с разным поведением и назначением."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 8, 2, 'Что такое callback_data?', '["Текст, который видит пользователь на кнопке", "Данные, которые отправляются боту при нажатии InlineKeyboard кнопки", "Название функции в коде", "Адрес сервера"]', '[2]', '{"1": "Неверно. Текст на кнопке — это параметр text, а callback_data — скрытые данные для бота.", "2": "✅ Правильно! callback_data — это данные, которые бот получает при клике на InlineKeyboard, невидимые пользователю.", "3": "Неверно. Название функции указывается в handler, callback_data — это строка с данными.", "4": "Неверно. callback_data — короткая строка с идентификатором действия, а не URL."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 8, 3, 'Зачем нужно меню навигации в боте?', '["Только для красоты интерфейса", "Для удобной навигации между разными функциями бота", "Это обязательное требование Telegram", "Чтобы бот работал быстрее"]', '[2]', '{"1": "Неверно. Меню критически важно для удобства пользователя, а не только для дизайна.", "2": "✅ Правильно! Меню помогает пользователю быстро находить нужные функции и улучшает UX.", "3": "Неверно. Telegram не требует меню, но хорошее меню повышает удобство использования.", "4": "Неверно. Меню влияет на удобство, но не на производительность бота."}', 0);

-- Урок 9
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 9, 1, 'Что такое FSM (Finite State Machine)?', '["База данных для ботов", "Система управления состояниями пользователя", "Библиотека для создания кнопок", "Способ отправки файлов"]', '[2]', '{"1": "Неверно. FSM — не база данных, а механизм управления состояниями диалога.", "2": "✅ Правильно! FSM позволяет боту помнить, на каком этапе диалога находится пользователь.", "3": "Неверно. FSM управляет состояниями диалога, а не интерфейсом кнопок.", "4": "Неверно. Отправка файлов — отдельная функция, FSM управляет логикой диалога."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 9, 2, 'Зачем нужно хранить контекст пользователя?', '["Чтобы бот мог вести многоэтапные диалоги", "Только для статистики", "Это не нужно", "Для отправки рекламы"]', '[1]', '{"1": "✅ Правильно! Контекст позволяет боту помнить предыдущие ответы и вести осмысленный диалог.", "2": "Неверно. Статистика — дополнительная возможность, основная задача — управление диалогом.", "3": "Неверно. Без контекста невозможны сложные сценарии вроде анкет или многошаговых операций.", "4": "Неверно. Контекст нужен для функциональности, а не для маркетинга."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 9, 3, 'Какие режимы работы можно реализовать через FSM?', '["Только режим вопрос-ответ", "Разные режимы: анкеты, тесты, многоэтапные операции", "Только отправку сообщений", "FSM не используется для режимов"]', '[2]', '{"1": "Неверно. FSM позволяет создавать сложные сценарии, а не только простые вопросы.", "2": "✅ Правильно! FSM дает возможность создавать разные режимы работы с переключением между ними.", "3": "Неверно. FSM управляет логикой взаимодействия, а не только отправкой сообщений.", "4": "Неверно. FSM — основа создания режимов работы бота."}', 0);

-- Урок 10
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 10, 1, 'Зачем боту нужна база данных?', '["Только для хранения токена", "Для сохранения пользователей, истории, настроек", "База данных не нужна ботам", "Только для хранения логов"]', '[2]', '{"1": "Неверно. Токен хранится в config, база нужна для данных пользователей.", "2": "✅ Правильно! База данных позволяет боту помнить пользователей, их данные и историю взаимодействий.", "3": "Неверно. База критически важна для ботов с долговременной памятью и персонализацией.", "4": "Неверно. Логи важны, но база используется шире — для всех данных приложения."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 10, 2, 'Почему SQLite подходит для начала работы?', '["Это самая быстрая база данных", "Не требует установки сервера, работает как файл", "Она бесплатная", "Только SQLite работает с Python"]', '[2]', '{"1": "Неверно. SQLite быстра для небольших данных, но главное — простота использования.", "2": "✅ Правильно! SQLite — встроенная БД, работающая как файл, идеальна для обучения и небольших проектов.", "3": "Неверно. Большинство БД бесплатны, преимущество SQLite — в отсутствии сервера.", "4": "Неверно. Python поддерживает множество БД, SQLite просто самая простая для старта."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 10, 3, 'Что такое таблица в базе данных?', '["Файл с кодом", "Структурированное хранилище данных с колонками и строками", "Список пользователей бота", "Графический интерфейс"]', '[2]', '{"1": "Неверно. Таблица — это структура данных внутри БД, а не файл с кодом.", "2": "✅ Правильно! Таблица — это структура данных, где каждая строка — запись, а колонка — поле данных.", "3": "Неверно. Список пользователей хранится В таблице, но таблица — это общее понятие структуры.", "4": "Неверно. Таблица — логическая структура данных, а не интерфейс."}', 0);

-- Урок 11
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 11, 1, 'Что нужно для подключения GigaChat к боту?', '["Только токен бота", "API ключ GigaChat и токен бота", "Специальный сервер", "Платная подписка"]', '[2]', '{"1": "Неверно. Токен бота нужен для работы с Telegram, но для GigaChat нужен отдельный API ключ.", "2": "✅ Правильно! Нужны два ключа: токен для Telegram и API ключ для GigaChat.", "3": "Неверно. Специальный сервер не требуется, работает через API запросы.", "4": "Неверно. GigaChat имеет бесплатный тариф для разработки и обучения."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 11, 2, 'Как бот отправляет запрос к нейросети?', '["Через веб-браузер", "Через HTTP запрос к API нейросети", "Через базу данных", "Через Telegram"]', '[2]', '{"1": "Неверно. Бот работает программно, без браузера, через API запросы.", "2": "✅ Правильно! Бот делает HTTP POST запрос к API GigaChat с текстом сообщения пользователя.", "3": "Неверно. База данных хранит данные, а запросы к нейросети идут через API.", "4": "Неверно. Telegram передает сообщение боту, но запрос к GigaChat идет напрямую через API."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (7, 11, 3, 'Зачем сохранять историю диалога с нейросетью?', '["Чтобы нейросеть помнила контекст разговора", "Только для статистики", "Это не нужно", "Для экономии запросов"]', '[1]', '{"1": "✅ Правильно! История диалога дает нейросети контекст, делая ответы более осмысленными и связными.", "2": "Неверно. Статистика полезна, но основная цель — обеспечить контекст для качественных ответов.", "3": "Неверно. Без истории нейросеть не помнит предыдущие сообщения, теряется смысл диалога.", "4": "Неверно. Каждый запрос отправляется с историей, это не экономит, но улучшает качество."}', 0);
